{
  "passageId": "audio-perceptual-coding",
  "items": [
    {
      "slot": 1,
      "stem": "윗글의 내용에 대한 이해로 적절하지 않은 것은?",
      "stemPolarity": "SELECT_INCORRECT",
      "choices": [
        {
          "number": 1,
          "text": "초기 녹음기가 소리를 아날로그 형태로 저장한 것과 달리, 현재는 소리를 이진수로 이루어진 디지털 신호로 바꾸어 파일에 저장한다."
        },
        {
          "number": 2,
          "text": "축음기는 바늘 아래에 회전판을 놓고 나팔에 소리를 들려주어, 소리로 생긴 나팔의 진동에 따라 바늘이 판에 홈을 만들도록 한다."
        },
        {
          "number": 3,
          "text": "한 오디오 파일에서는 모든 소리 크기에 균일한 개수의 비트를 할당하며, 소리 크기가 달라도 동일한 이진수 값으로 기록한다."
        },
        {
          "number": 4,
          "text": "오디오 파일은 저장하거나 네트워크로 전송하기에 데이터 양이 많으므로, 저장 공간을 아끼고 전송이 가능하도록 신호를 압축할 필요가 있다."
        },
        {
          "number": 5,
          "text": "소리를 디지털 신호로 바꾸어 저장할 때 각 소리 크기에 할당하는 비트의 개수를 늘리면, 소리는 아날로그 원음에 더 가까워진다."
        }
      ],
      "answer": 3
    },
    {
      "slot": 2,
      "stem": "윗글의 내용에 대한 이해로 적절한 것은?",
      "stemPolarity": "SELECT_CORRECT",
      "choices": [
        {
          "number": 1,
          "text": "최소가청강도는 주변에 큰 소리가 존재하는 상황에서 청각이 감지할 수 있는 소리 크기의 최솟값을 뜻한다."
        },
        {
          "number": 2,
          "text": "최소가청강도는 주파수별로 달라서, 100 Hz 이하에서는 1,000∼10,000 Hz에서보다 소리가 훨씬 커야 들린다."
        },
        {
          "number": 3,
          "text": "지각부호화는 청각 특성을 이용하는 압축 기술로, 청각의 감도가 높은 소리를 제거하는 방식으로 오디오 신호를 압축한다."
        },
        {
          "number": 4,
          "text": "소리 크기와 차폐 문턱값의 차이가 작을수록 비트를 많이 할당하여 소리의 손실을 낮춤으로써, 압축에 따른 품질 저하를 최소화한다."
        },
        {
          "number": 5,
          "text": "소리 크기를 최소가청강도와 비교하면, 그보다 큰 소리는 청각으로 감지할 수 없지만 그보다 작은 소리는 감지할 수 있다."
        }
      ],
      "answer": 2
    },
    {
      "slot": 3,
      "stem": "임계대역에 대한 이해로 적절한 것은?",
      "stemPolarity": "SELECT_CORRECT",
      "choices": [
        {
          "number": 1,
          "text": "두 소리의 주파수가 충분히 멀어져야 차폐가 일어나므로, 임계대역은 차폐음에서 주파수가 멀리 떨어진 소리들이 차폐되는 구간이다."
        },
        {
          "number": 2,
          "text": "임계대역의 폭은 차폐를 일으키는 소리의 주파수에 따라 달라지며, 차폐음이 저음일 때의 폭이 고음일 때의 폭보다 훨씬 넓다."
        },
        {
          "number": 3,
          "text": "임계대역은 큰 소리에 의해 차폐되어 들리지 않는 작은 소리의 주파수를 기준으로, 차폐가 가능한 최저 주파수와 최고 주파수 사이로 정해지는 구간이다."
        },
        {
          "number": 4,
          "text": "임계대역은 차폐음 기준으로 차폐가 가능한 최저·최고 주파수 사이의 구간으로, 지각부호화에서 신호를 나누어 대역별 차폐 문턱값을 구할 때 이용된다."
        },
        {
          "number": 5,
          "text": "지각부호화에서는 최소가청강도와 차폐음을 고려하여 차폐 문턱값을 먼저 구한 다음, 오디오 신호를 주파수에 따라 여러 임계대역으로 나눈다."
        }
      ],
      "answer": 4
    }
  ]
}

